import numpy as np
X=[10,12,15,30,33,37,41,90]
def km(c):
    c=[float(v) for v in c]; prev=None
    while True:
        lab=[int(abs(x-c[1])<abs(x-c[0])) for x in X]
        assert all(abs(abs(x-c[0])-abs(x-c[1]))>1e-9 for x in X)
        if lab==prev: break
        prev=lab; c=[np.mean([x for x,l in zip(X,lab) if l==k]) for k in (0,1)]
    return lab,c,sum((x-c[l])**2 for x,l in zip(X,lab))
for init in [(12,33),(10,90)]: print(init,km(init))
